-- The tables youtube_ML creates in db.sqlite3 (Django migration catalog 0001).
-- Copied from that file so the sample has the same schema. Keep it in step with
-- youtube_ML/catalog/models.py.
CREATE TABLE "catalog_channel" ("id" varchar(32) NOT NULL PRIMARY KEY, "title" varchar(200) NOT NULL, "description" text NOT NULL, "custom_url" varchar(100) NOT NULL, "country" varchar(8) NOT NULL, "published" datetime NULL, "thumbnail" varchar(500) NOT NULL, "uploads_playlist_id" varchar(64) NOT NULL, "synced_at" datetime NULL);
CREATE TABLE "catalog_playlist" ("id" varchar(64) NOT NULL PRIMARY KEY, "title" varchar(200) NOT NULL, "description" text NOT NULL, "published" datetime NULL, "item_count" integer NOT NULL, "privacy_status" varchar(16) NOT NULL, "synced_at" datetime NULL, "channel_id" varchar(32) NOT NULL REFERENCES "catalog_channel" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "catalog_video" ("id" varchar(11) NOT NULL PRIMARY KEY, "title" varchar(200) NOT NULL, "description" text NOT NULL, "published" datetime NULL, "duration_seconds" integer NOT NULL, "category_id" varchar(8) NOT NULL, "category" varchar(60) NOT NULL, "language" varchar(16) NOT NULL, "audio_language" varchar(16) NOT NULL, "definition" varchar(8) NOT NULL, "caption" bool NOT NULL, "licensed_content" bool NULL, "privacy_status" varchar(16) NOT NULL, "license" varchar(32) NOT NULL, "embeddable" bool NULL, "made_for_kids" bool NULL, "thumbnail" varchar(500) NOT NULL, "tags" text NOT NULL CHECK ((JSON_VALID("tags") OR "tags" IS NULL)), "topics" text NOT NULL CHECK ((JSON_VALID("topics") OR "topics" IS NULL)), "synced_at" datetime NULL, "channel_id" varchar(32) NOT NULL REFERENCES "catalog_channel" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "catalog_channelsnapshot" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "taken_on" date NOT NULL, "subscriber_count" bigint NOT NULL, "view_count" bigint NOT NULL, "video_count" integer NOT NULL, "channel_id" varchar(32) NOT NULL REFERENCES "catalog_channel" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "one_channel_snapshot_per_day" UNIQUE ("channel_id", "taken_on"));
CREATE TABLE "catalog_playlistitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "video_id" varchar(11) NOT NULL, "position" integer NOT NULL, "added" datetime NULL, "playlist_id" varchar(64) NOT NULL REFERENCES "catalog_playlist" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "one_item_per_position" UNIQUE ("playlist_id", "position"));
CREATE TABLE "catalog_videostats" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "taken_on" date NOT NULL, "view_count" bigint NOT NULL, "like_count" bigint NOT NULL, "comment_count" bigint NOT NULL, "video_id" varchar(11) NOT NULL REFERENCES "catalog_video" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "one_video_stats_per_day" UNIQUE ("video_id", "taken_on"));
CREATE INDEX "catalog_playlist_channel_id_67e8e7f2" ON "catalog_playlist" ("channel_id");
CREATE INDEX "catalog_video_published_9770928b" ON "catalog_video" ("published");
CREATE INDEX "catalog_video_channel_id_7f3315c9" ON "catalog_video" ("channel_id");
CREATE INDEX "catalog_channelsnapshot_channel_id_84ec0fb3" ON "catalog_channelsnapshot" ("channel_id");
CREATE INDEX "catalog_playlistitem_video_id_e892c492" ON "catalog_playlistitem" ("video_id");
CREATE INDEX "catalog_playlistitem_playlist_id_7a8aef11" ON "catalog_playlistitem" ("playlist_id");
CREATE INDEX "catalog_videostats_video_id_8adb5a25" ON "catalog_videostats" ("video_id");
